# Generated by Claude Code. v1.0 (PoC 2), restyled to the approved v2 design in v1.1.
# Regenerates the Healthy Retention report pages, theme and navigation (PBIR).
# Run from the powerbi/ folder: python ../tools/gen_report.py HealthyRetention.Report

"""Generate Healthy Retention PBIR report pages and theme (v2 design).

Usage: python gen_report.py <path to HealthyRetention.Report>
Writes only inside the report folder. Never touches the semantic model.
Design reference: docs/design/*.dc.html. Brief: docs/claude_code_brief_v2.md.
"""
import json
import shutil
import sys
from pathlib import Path

REPORT = Path(sys.argv[1])
DEF = REPORT / "definition"
PAGES = DEF / "pages"
SCHEMA = "https://developer.microsoft.com/json-schemas/fabric/item/report/definition"

# ---------- palette (brief v2) ----------
BG, HEAD, PANEL, BORDER = "#1F2A33", "#17212A", "#26333E", "#36454F"
TAB_ON, INSET = "#2F4050", "#222D36"
TXT, TXT2, MUTED, NEUTRAL = "#E8EEF2", "#9DB0BE", "#7D8F9C", "#C9D4DC"
GREEN, RED = "#4CC26A", "#E5484D"
BLUE, LIGHT, PURPLE, LIME, YELLOW, CYAN, SALMON = (
    "#4C8DF6", "#7EB6FF", "#8A6CF0", "#9BD15A", "#E5E067", "#6ED6E8", "#E39A86")
PAL = [BLUE, LIGHT, PURPLE, LIME, YELLOW, CYAN, SALMON]
DARK_LABEL = "#17212A"  # label text on bright bars
SOURCE = "Source: Ghaharian et al. (2023), Mendeley Data, CC BY 4.0"
FOOT_RIGHT = "Casino brand · v1.0 · Pacific time · USD"
PROXY = "“High-intensity” is a spending proxy, not confirmed harm"

written = []


def write(path: Path, obj):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    written.append(path)


# ---------- expression helpers ----------
def lit(v):
    if isinstance(v, bool):
        s = "true" if v else "false"
    elif isinstance(v, int):
        s = f"{v}L"
    elif isinstance(v, float):
        s = f"{v}D"
    else:
        s = "'" + str(v).replace("'", "''") + "'"
    return {"expr": {"Literal": {"Value": s}}}


def num(v):  # formatting numbers are doubles
    return {"expr": {"Literal": {"Value": f"{v}D"}}}


def color(c):
    return {"solid": {"color": lit(c)}}


def col(table, name):
    return {"Column": {"Expression": {"SourceRef": {"Entity": table}}, "Property": name}}


def meas(name, table="_Measures"):
    return {"Measure": {"Expression": {"SourceRef": {"Entity": table}}, "Property": name}}


def proj(field, display=None):
    inner = field.get("Column") or field.get("Measure")
    ent = inner["Expression"]["SourceRef"]["Entity"]
    p = {"field": field, "queryRef": f"{ent}.{inner['Property']}", "nativeQueryRef": inner["Property"]}
    if display:
        p["displayName"] = display
    return p


def qref(field):
    inner = field.get("Column") or field.get("Measure")
    return f"{inner['Expression']['SourceRef']['Entity']}.{inner['Property']}"


def src_col(alias, name):
    return {"Column": {"Expression": {"SourceRef": {"Source": alias}}, "Property": name}}


def in_values(values):
    out = []
    for v in values:
        if isinstance(v, str) and v.startswith("datetime'"):
            out.append([{"Literal": {"Value": v}}])
        else:
            out.append([{"Literal": {"Value": "'" + v.replace("'", "''") + "'"}}])
    return out


_fid = [0]


def fname(prefix):
    _fid[0] += 1
    return f"{prefix}_f{_fid[0]:02d}"


def f_in(table, column, values, prefix, exclude=False):
    cond = {"In": {"Expressions": [src_col("d", column)], "Values": in_values(values)}}
    if exclude:
        cond = {"Not": {"Expression": cond}}
    f = {
        "name": fname(prefix),
        "field": col(table, column),
        "type": "Categorical",
        "filter": {"Version": 2, "From": [{"Name": "d", "Entity": table, "Type": 0}],
                   "Where": [{"Condition": cond}]},
        "howCreated": "User",
    }
    if exclude:
        f["objects"] = {"general": [{"properties": {"isInvertedSelectionMode": lit(True)}}]}
    return f


def f_not_blank(table, column, prefix):
    return {
        "name": fname(prefix),
        "field": col(table, column),
        "type": "Advanced",
        "filter": {"Version": 2, "From": [{"Name": "d", "Entity": table, "Type": 0}],
                   "Where": [{"Condition": {"Not": {"Expression": {"Comparison": {
                       "ComparisonKind": 0, "Left": src_col("d", column),
                       "Right": {"Literal": {"Value": "null"}}}}}}}]},
        "howCreated": "User",
    }


def f_between_int(table, column, lo, hi, prefix):
    left = {"Comparison": {"ComparisonKind": 2, "Left": src_col("d", column), "Right": {"Literal": {"Value": f"{lo}L"}}}}
    right = {"Comparison": {"ComparisonKind": 4, "Left": src_col("d", column), "Right": {"Literal": {"Value": f"{hi}L"}}}}
    return {
        "name": fname(prefix),
        "field": col(table, column),
        "type": "Advanced",
        "filter": {"Version": 2, "From": [{"Name": "d", "Entity": table, "Type": 0}],
                   "Where": [{"Condition": {"And": {"Left": left, "Right": right}}}]},
        "howCreated": "User",
    }


def months(start, end):
    (y, m), out = start, []
    while (y, m) <= end:
        out.append(f"datetime'{y}-{m:02d}-01T00:00:00'")
        y, m = (y + 1, 1) if m == 12 else (y, m + 1)
    return out


def page_filters(prefix, cohort=None, new=True, extra=()):
    fs = [f_in("dim_player", "brand", ["casino"], prefix)]
    if new:
        fs.append(f_in("dim_player", "player_type", ["new"], prefix))
    if cohort:
        fs.append(f_in("dim_player", "cohort_month", months(*cohort), prefix))
    fs.extend(extra)
    for i, f in enumerate(fs):
        f["ordinal"] = i
    return {"filters": fs, "filterSortOrder": "Custom"}


# ---------- page + container helpers ----------
class Page:
    def __init__(self, name, display, width=1280, height=720):
        self.name, self.display, self.w, self.h = name, display, width, height
        self.visuals, self.z = [], 0

    def add(self, vname, rect, visual, filters=None, hidden=False):
        x, y, w, h = rect
        self.z += 1
        vc = {
            "$schema": f"{SCHEMA}/visualContainer/2.2.0/schema.json",
            "name": vname,
            "position": {"x": x, "y": y, "z": self.z * 1000, "height": h, "width": w, "tabOrder": self.z * 1000},
            "visual": visual,
        }
        if filters:
            vc["filterConfig"] = {"filters": filters}
        if hidden:
            vc["isHidden"] = True
        self.visuals.append(vc)
        return vname


def text_px(text, size_pt):
    """Conservative width estimate for Segoe UI text (0.55 em per character)."""
    return len(text) * size_pt * 4 / 3 * 0.55


def check_fits(text, size_pt, width):
    """Fail the build instead of shipping clipped or wrapping one-line text (v1.1 fix #2, #5)."""
    need = text_px(text, size_pt)
    if need > width - 6:
        raise SystemExit(f"Text does not fit ({need:.0f}px > {width - 6}px): {text!r}")


def vco(title=None, title_expr=None, title_size=14, subtitle=None, subtitle_expr=None,
        panel=True, fill=None, border_color=None, radius=4, tooltip_page=None, link=None, padding=None):
    """Visual container formatting: v2 panel (bg #26333E, 1px border, radius 4) + title with divider.
    padding=(top, right, bottom, left) in px; used on one-line text boxes and header slicers."""
    o = {}
    if padding is not None:
        t, r, b, l = padding
        o["padding"] = [{"properties": {"top": num(t), "right": num(r), "bottom": num(b), "left": num(l)}}]
    if title is not None or title_expr is not None:
        o["title"] = [{"properties": {
            "show": lit(True),
            "text": {"expr": title_expr} if title_expr else lit(title),
            "fontSize": num(title_size), "fontColor": color(TXT),
            "fontFamily": lit("Segoe UI Semibold"), "alignment": lit("left")}}]
        o["divider"] = [{"properties": {"show": lit(True), "color": color(BORDER)}}]
    else:
        o["title"] = [{"properties": {"show": lit(False)}}]
    if subtitle is not None or subtitle_expr is not None:
        o["subTitle"] = [{"properties": {
            "show": lit(True),
            "text": {"expr": subtitle_expr} if subtitle_expr else lit(subtitle),
            "fontSize": num(8), "fontColor": color(TXT2), "alignment": lit("left")}}]
    if panel:
        o["background"] = [{"properties": {"show": lit(True), "color": color(fill or PANEL),
                                           "transparency": num(0)}}]
        o["border"] = [{"properties": {"show": lit(True), "color": color(border_color or BORDER),
                                       "radius": num(radius), "width": num(1)}}]
    else:
        o["background"] = [{"properties": {"show": lit(False)}}]
        o["border"] = [{"properties": {"show": lit(False)}}]
    o["dropShadow"] = [{"properties": {"show": lit(False)}}]
    if tooltip_page:
        o["visualTooltip"] = [{"properties": {"show": lit(True), "type": lit("Canvas"),
                                              "section": lit(tooltip_page)}}]
    if link:
        o["visualLink"] = [{"properties": link}]
    return o


def textbox(paragraphs, **kw):
    kw.setdefault("panel", False)
    return {
        "visualType": "textbox",
        "objects": {"general": [{"properties": {"paragraphs": paragraphs}}]},
        "visualContainerObjects": vco(**kw),
        "drillFilterOtherVisuals": True,
    }


def run(text, size=10, c=TXT, bold=False):
    style = {"fontFamily": "Segoe UI Semibold" if bold else "Segoe UI", "fontSize": f"{size}pt", "color": c}
    return {"value": text, "textStyle": style}


def para(*runs, align="left"):
    return {"textRuns": list(runs), "horizontalTextAlignment": align}


def shape(fill):
    return {
        "visualType": "shape",
        "objects": {
            "shape": [{"properties": {"tileShape": lit("rectangle")}}],
            "fill": [{"properties": {"show": lit(True), "fillColor": color(fill), "transparency": num(0)},
                      "selector": {"id": "default"}}],
            "outline": [{"properties": {"show": lit(False)}}],
        },
        "visualContainerObjects": vco(panel=False),
        "drillFilterOtherVisuals": True,
    }


def chart(vtype, roles, sort=None, objects=None, field_params=None, **kw):
    qs = {role: {"projections": ps} for role, ps in roles.items()}
    if field_params:
        for role, fp in field_params.items():
            qs[role]["fieldParameters"] = fp
    q = {"queryState": qs}
    if sort:
        q["sortDefinition"] = {"sort": sort}
    v = {"visualType": vtype, "query": q, "drillFilterOtherVisuals": True}
    if objects:
        v["objects"] = objects
    v["visualContainerObjects"] = vco(**kw)
    return v


def cat_colors(field, mapping, default=None, metadata=None):
    """Per-category (or per-series) fill colours."""
    out = [{"properties": {"fill": color(default)}}] if default else []
    for value, c in mapping.items():
        sel = {"data": [{"scopeId": {"Comparison": {"ComparisonKind": 0, "Left": field,
                                                    "Right": {"Literal": {"Value": "'" + value + "'"}}}}}]}
        if metadata:
            sel["metadata"] = metadata
        out.append({"properties": {"fill": color(c)}, "selector": sel})
    return out


def series_colors(pairs):
    """Fill per measure (series) for multi-measure charts."""
    return [{"properties": {"fill": color(c)}, "selector": {"metadata": qref(m)}} for m, c in pairs]


def labels_on(c=TXT, size=9, extra=None, precision=None):
    # display units None: counts show 1,069 instead of 1K (v1.1 fix #6)
    p = {"show": lit(True), "color": color(c), "fontSize": num(size), "labelDisplayUnits": num(1)}
    if precision is not None:
        p["labelPrecision"] = lit(precision)
    if extra:
        p.update(extra)
    return [{"properties": p}]


def axes(val_show=False, categorical=False, cat_show=True):
    cat = {"show": lit(cat_show), "showAxisTitle": lit(False), "labelColor": color(NEUTRAL)}
    if categorical:
        cat["axisType"] = lit("Categorical")
    return {
        "categoryAxis": [{"properties": cat}],
        "valueAxis": [{"properties": {"show": lit(val_show), "showAxisTitle": lit(False),
                                      "labelColor": color(TXT2), "gridlineShow": lit(val_show),
                                      "gridlineColor": color(BORDER)}}],
    }


def legend(show=True, position="Top"):
    return [{"properties": {"show": lit(show), "position": lit(position), "labelColor": color(TXT2),
                            "fontSize": num(8), "showTitle": lit(False)}}]


def button(text, text_color, fill=None, link=None, size=10, hover=PANEL, border=None):
    objs = {
        "icon": [{"properties": {"show": lit(False)}, "selector": {"id": "default"}}],
        "text": [{"properties": {"show": lit(True), "text": lit(text), "fontColor": color(text_color),
                                 "fontSize": num(size), "fontFamily": lit("Segoe UI Semibold")},
                  "selector": {"id": "default"}}],
        "fill": [{"properties": {"show": lit(fill is not None), "fillColor": color(fill or HEAD),
                                 "transparency": num(0)}, "selector": {"id": "default"}},
                 {"properties": {"show": lit(True), "fillColor": color(hover), "transparency": num(0)},
                  "selector": {"id": "hover"}}],
        "outline": [{"properties": {"show": lit(border is not None), "lineColor": color(border or BORDER)},
                     "selector": {"id": "default"}}],
    }
    return {"visualType": "actionButton", "objects": objs,
            "visualContainerObjects": vco(panel=False, link=link),
            "drillFilterOtherVisuals": True}


def page_navigator():
    """Built-in page navigator as horizontal tabs (v1.1 fix #1: replaces hand-made buttons that showed
    no text). Hidden pages (Player list, tooltip) are left out by the navigator itself."""
    st = lambda sid, **p: {"properties": p, "selector": {"id": sid}}
    return {
        "visualType": "pageNavigator",
        "objects": {
            "layout": [{"properties": {"orientation": num(0)}}],
            "fill": [st("default", show=lit(True), fillColor=color(HEAD), transparency=num(0)),
                     st("hover", show=lit(True), fillColor=color(PANEL), transparency=num(0)),
                     st("selected", show=lit(True), fillColor=color(TAB_ON), transparency=num(0))],
            "text": [st("default", fontColor=color(TXT2), fontSize=num(9), fontFamily=lit("Segoe UI"),
                        horizontalAlignment=lit("center")),
                     st("hover", fontColor=color(TXT)),
                     st("selected", fontColor=color(TXT), fontFamily=lit("Segoe UI Semibold"))],
            "outline": [st("default", show=lit(False))],
        },
        "visualContainerObjects": vco(panel=False),
        "drillFilterOtherVisuals": True,
    }


# ---------- layout (1280 x 720, header 64, main padding 12/16, gap 12) ----------
X0, W, GAP = 16, 1248, 12
TOP_Y, TOP_H = 76, 328
BOT_Y, BOT_H = 416, 272


def split(x, w, ratios, gap=GAP):
    total = sum(ratios)
    avail = w - gap * (len(ratios) - 1)
    out, cx = [], x
    for i, r in enumerate(ratios):
        cw = round(avail * r / total) if i < len(ratios) - 1 else x + w - cx
        out.append((cx, cw))
        cx += cw + gap
    return out


def top(left=1.0, right=1.2):
    (lx, lw), (rx, rw) = split(X0, W, [left, right])
    return (lx, TOP_Y, lw, TOP_H), (rx, TOP_Y, rw, TOP_H)


def bottom(*ratios):
    return [(x, BOT_Y, w, BOT_H) for x, w in split(X0, W, list(ratios or (1, 1, 1)))]


def grid(rect, cols=3, rows=2):
    x, y, w, h = rect
    xs = split(x, w, [1] * cols)
    ys = split(y, h, [1] * rows)
    return [(cx, cy, cw, ch) for cy, ch in ys for cx, cw in xs]


# ---------- header + footer ----------
P1, P2, P3, P4, P5, P6, P7 = ("deposit_journey", "retention", "segments", "healthy_retention",
                              "payment_friction", "player_list", "tooltip_journey")
NO_PAD = (0, 0, 0, 0)
NAV_X, NAV_W = 200, 600  # page navigator: 5 equal tabs of 120 px


def header(pg: Page, nav=True, controls=()):
    """controls: list of (label, label_width, visual, visual_width, visual_height), laid out right to left.
    One-line text boxes get padding 0 and enough height, so they never overflow into a scrollbar
    (the stray white rectangles of v1.1, fix #3)."""
    pg.add("hdr_bar", (0, 0, 1280, 64), shape(HEAD))
    check_fits("Healthy Retention", 14, 184)
    pg.add("hdr_title", (16, 12, 184, 40),
           textbox([para(run("Healthy Retention", 14, TXT, bold=True))], padding=NO_PAD))
    if nav:
        for tab in ("Journey", "Retention", "Segments", "Healthy retention", "Friction"):
            check_fits(tab, 9, NAV_W // 5)
        pg.add("hdr_nav", (NAV_X, 12, NAV_W, 40), page_navigator())
    xr = 1256
    for i, (label, lw, visual, vw, vh) in enumerate(reversed(controls)):
        xr -= vw
        pg.add(f"hdr_ctl_{i}", (xr, (64 - vh) // 2, vw, vh), visual)
        xr -= lw + 4
        check_fits(label, 10, lw)
        pg.add(f"hdr_lbl_{i}", (xr, 20, lw, 24),
               textbox([para(run(label, 10, TXT), align="right")], padding=NO_PAD))
        xr -= 16
    if nav and xr < NAV_X + NAV_W:
        raise SystemExit(f"Header controls on {pg.name} overlap the page navigator")


def footer(pg: Page, left_note=None, right=FOOT_RIGHT):
    """Footer split sized to the right-hand text, so the left line gets all remaining width (fix #5)."""
    text = SOURCE + (f" · {left_note}" if left_note else "")
    rw = round(text_px(right, 8)) + 12
    lw = W - rw
    check_fits(text, 8, lw)
    check_fits(right, 8, rw)
    pg.add("footer_left", (X0, 694, lw, 22), textbox([para(run(text, 8, MUTED))], padding=NO_PAD))
    pg.add("footer_right", (X0 + lw, 694, rw, 22),
           textbox([para(run(right, 8, MUTED), align="right")], padding=NO_PAD))


def dropdown(field, display):
    # 40 px tall with no vertical padding, so the selected value is fully visible (fix #4)
    return {
        "visualType": "slicer",
        "query": {"queryState": {"Values": {"projections": [proj(field, display)]}}},
        "objects": {"data": [{"properties": {"mode": lit("Dropdown")}}],
                    "header": [{"properties": {"show": lit(False)}}],
                    "items": [{"properties": {"fontColor": color(TXT), "background": color(BG),
                                              "textSize": num(10)}}]},
        "visualContainerObjects": vco(fill=BG, border_color=TXT2, radius=2, padding=(0, 4, 0, 4)),
        "drillFilterOtherVisuals": True,
    }


COHORT = col("dim_player", "cohort_month")
COHORT_CTL = ("Cohort:", 58, dropdown(COHORT, "Cohort"), 150, 40)


# ---------- KPI cards and panels ----------
def card(measure, title, subtitle, value_color, units=1, precision=None):
    lab = {"color": color(value_color), "fontSize": num(32), "fontFamily": lit("Segoe UI"),
           "labelDisplayUnits": num(units)}
    if precision is not None:
        lab["labelPrecision"] = lit(precision)
    return chart("card", {"Values": [proj(meas(measure), subtitle)]},
                 objects={"labels": [{"properties": lab}],
                          "categoryLabels": [{"properties": {"show": lit(True), "color": color(TXT2),
                                                             "fontSize": num(8)}}]},
                 title=title, title_size=13)


def missing(measure_name, size=32):
    """Placeholder body for a KPI or chart whose measure does not exist yet (brief v2: no hard-coded numbers)."""
    return [para(run("—", size, MUTED), align="center"),
            para(run(f"Needs measure: [{measure_name}]", 8, MUTED), align="center")]


def kpis(pg: Page, rect, items):
    """items: (vname, kind, args, filters). kind 'card' -> card(*args); 'missing' -> (title, measure)."""
    for r, (vname, kind, args, filters) in zip(grid(rect), items):
        if kind == "card":
            pg.add(vname, r, card(*args), filters=filters)
        else:
            title, mname = args
            pg.add(vname, r, textbox(missing(mname), title=title, title_size=13, panel=True))


def placeholder_panel(pg, vname, rect, title, measure_name, note=None):
    body = [para(run("", 10))] * 3 + missing(measure_name, 24)
    if note:
        body.append(para(run(note, 8, MUTED), align="center"))
    pg.add(vname, rect, textbox(body, title=title, panel=True))


def text_panel(pg, vname, rect, title, paragraphs):
    pg.add(vname, rect, textbox(paragraphs, title=title, panel=True))


def save_page(pg: Page, filter_config=None, extra=None):
    p = {
        "$schema": f"{SCHEMA}/page/2.0.0/schema.json",
        "name": pg.name,
        "displayName": pg.display,
        "displayOption": "FitToPage",
        "height": pg.h,
        "width": pg.w,
    }
    if filter_config:
        p["filterConfig"] = filter_config
    if extra:
        p.update(extra)
    # remove visuals from earlier versions so nothing stale is left behind
    shutil.rmtree(PAGES / pg.name / "visuals", ignore_errors=True)
    write(PAGES / pg.name / "page.json", p)
    for vc in pg.visuals:
        write(PAGES / pg.name / "visuals" / vc["name"] / "visual.json", vc)


