# ---------------- report.json: register custom theme ----------------
rp = DEF / "report.json"
report = json.loads(rp.read_text(encoding="utf-8"))
base_ver = report["themeCollection"]["baseTheme"]["reportVersionAtImport"]
report["themeCollection"]["customTheme"] = {"name": THEME_NAME, "reportVersionAtImport": base_ver,
                                            "type": "RegisteredResources"}
pkgs = [p for p in report["resourcePackages"] if p["name"] != "RegisteredResources"]
pkgs.append({"name": "RegisteredResources", "type": "RegisteredResources",
             "items": [{"name": THEME_NAME, "path": THEME_NAME, "type": "CustomTheme"}]})
report["resourcePackages"] = pkgs
write(rp, report)

# ---------------- pages.json + hide any extra (verification) pages ----------------
pj = PAGES / "pages.json"
meta = json.loads(pj.read_text(encoding="utf-8"))
new_pages = [P1, P2, P3, P4, P5, P6, P7]
old_pages = [p for p in meta["pageOrder"] if p not in new_pages]
meta["pageOrder"] = new_pages + old_pages
meta["activePageName"] = P1
write(pj, meta)
for p in old_pages:
    f = PAGES / p / "page.json"
    d = json.loads(f.read_text(encoding="utf-8"))
    d["visibility"] = "HiddenInViewMode"
    write(f, d)

